"""ARENA u06 的 10 道测验（沿用旧版题目，调整了解释措辞）"""
from unitlib import Q
QUIZ = [
  Q('特征向量 $\\mathbf{v}$ 满足 $A\\mathbf{v} = \\lambda\\mathbf{v}$，几何上意味着什么？', ['变换后 $\\mathbf{v}$ 仍在原来经过原点的那条直线上，只是被缩放了 $\\lambda$ 倍', '$\\mathbf{v}$ 在变换后长度不变', '$\\mathbf{v}$ 被旋转了 $\\lambda$ 度', '$\\mathbf{v}$ 被送到原点'], 0, '特征向量的方向保持不变（或正好反向），只被缩放。长度不变只在 $|\\lambda| = 1$ 时成立。'),
  Q('$A = \\begin{bmatrix} 4 & 0 \\\\ 0 & -1 \\end{bmatrix}$ 的特征值是？', ['4 和 1', '0 和 3', '4 和 −1', '只有 4'], 2, '对角矩阵的特征值就是对角线元素：4 和 −1。$\\lambda = -1$ 表示 $\\hat{\\jmath}$ 方向被翻转。'),
  Q('求特征值时解的方程是？', ['$\\det(A) = \\lambda$', '$\\text{tr}(A - \\lambda I) = 0$', '$A - \\lambda = 0$', '$\\det(A - \\lambda I) = 0$'], 3, '$(A - \\lambda I)\\mathbf{v} = \\mathbf{0}$ 有非零解 ⇔ $A - \\lambda I$ 不可逆 ⇔ 行列式为 0。'),
  Q('二维平面里的 90° 旋转矩阵有实数特征向量吗？', ['有，是 $\\hat{\\imath}$', '没有，每个非零向量都被转离了原来的直线', '有无穷多个', '有，是 $\\hat{\\jmath}$'], 1, '旋转 90° 后没有任何非零向量留在原来的直线上，所以没有实特征向量（特征值是复数 $\\pm i$）。'),
  Q('一个 2×2 矩阵的特征值是 2 和 5，它的迹和行列式分别是？', ['迹 7，行列式 10', '迹 10，行列式 7', '迹 3，行列式 10', '迹 7，行列式 3'], 0, '迹 = 特征值之和 = 7；行列式 = 特征值之积 = 10。'),
  Q('对角化 $A = PDP^{-1}$ 中，$P$ 的列是什么？', ['特征值', '$A$ 的行', '$A$ 的奇异值', '$A$ 的特征向量'], 3, '$P$ 把特征基坐标翻译回标准坐标，所以它的列是特征向量；$D$ 的对角线是对应的特征值。'),
  Q('SVD $A = U\\Sigma V^\\top$ 的几何含义是？', ['平移 → 缩放 → 平移', '旋转（或反射）→ 沿坐标轴缩放 → 旋转（或反射）', '缩放 → 剪切 → 缩放', '只是一次旋转'], 1, '$V^\\top$ 和 $U$ 都是正交矩阵（旋转 / 反射），$\\Sigma$ 沿坐标轴缩放。从右往左：先 $V^\\top$，再 $\\Sigma$，最后 $U$。'),
  Q('关于 SVD，下面哪个说法正确？', ['只适用于方阵', '只适用于对称矩阵', '对任意形状的实矩阵都存在', '奇异值可能是负数'], 2, 'SVD 对任何 $m \\times n$ 实矩阵都存在，奇异值总是非负的。这正是它比特征分解更通用的地方。'),
  Q('一个矩阵的奇异值是 5, 2, 0, 0，它的秩是多少？', ['2', '4', '0', '7'], 0, '秩 = 非零奇异值的个数 = 2。'),
  Q('保留最大的 $k$ 个奇异值得到的 $\\sum_{i=1}^k \\sigma_i\\mathbf{u}_i\\mathbf{v}_i^\\top$ 有什么意义？', ['它就是 $A$ 的逆矩阵', '它是 $A$ 的特征向量', '它的行列式等于 $A$ 的行列式', '它是所有秩为 $k$ 的矩阵中对 $A$ 最好的近似'], 3, '这就是低秩近似（Eckart–Young 定理），PCA、图像压缩、分析 Transformer 权重都用到它。'),
]
